import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateTeamHandler } from "../handlers/updateTeamHandler";
import type { ApiError } from "../runtime/client";
import type { UpdateTeamRequest } from "../types/UpdateTeamRequest";

type Data = Awaited<ReturnType<typeof updateTeamHandler>>;
type Vars = { username: string; body: UpdateTeamRequest };

export function useUpdateTeam(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateTeamHandler(vars.username, vars.body),
    ...options,
  });
}
